package ru.hive13.server;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import ru.hive13.model.*;
import static ru.hive13.model.Model.*;
import java.util.*;
import java.nio.file.Path;

class CampaignCompletionTest {
    @Test void voluntaryIntegrationChangesActualTargetingWithoutRemovingTheCreature(){var e=chapter(6);var h=e.state.creatures.getFirst();var a=e.state.actor(0);a.roomId=h.roomId;a.x=h.x;a.y=h.y;e.state.flags.add("attuned_0");e.advance(.5);assertEquals(100,a.hp);assertEquals(2,e.state.creatures.size());var other=e.state.actor(1);other.roomId=h.roomId;other.x=h.x;other.y=h.y;e.advance(.1);assertTrue(other.hp<100);assertEquals(100,a.hp);}
    @Test void eachFinalRouteExecutesItsFullPhysicalChainAndChargesSupplies(){for(String route:CampaignPlan.ROUTES){var e=chapter(6);var s=e.state;s.finalRoute=route;s.flags.add("route_"+route);s.flags.addAll(List.of("key_0","key_1","key_2","origin_signatures","city_dates","eva_met","d00_known","pact_followers","hor_contact","ecology_proven","pact_kovcheg","network_audit","ai_lies_proved"));for(var a:s.actors)a.permissions.addAll(CampaignPlan.PERMISSIONS);
        String[][] chain=switch(route){case "exodus"->new String[][]{{"node_tunnel","N_TUNNEL"},{"node_beacon","N_BEACON"},{"node_control","N_CONVOY"}};case "bastion"->new String[][]{{"node_tunnel","N_PRESSURE"},{"node_beacon","N_VENT"},{"node_a","N_SYNC_A"},{"node_b","N_SYNC_B"}};case "cleansing"->new String[][]{{"node_tunnel","N_CUT"},{"node_beacon","N_RUNOFF"},{"node_control","N_HEAT"}};case "symbiosis"->new String[][]{{"node_control","N_RESONANCE"},{"node_bio","N_BLOOD"}};case "protocol"->new String[][]{{"node_control","N_AUDIT"},{"node_final","N_OFFLINE"},{"node_final","N_PROTOCOL"}};default->new String[][]{{"node_control","N_KEYS"},{"node_anchor","N_ANCHOR"},{"node_a","N_SYNC_A"},{"node_b","N_SYNC_B"},{"node_final","N_STOP"}};};
        for(var operation:chain)use(e,operation[1].equals("N_SYNC_B")?1:0,operation[0],operation[1]);if(route.equals("symbiosis"))for(int slot=0;slot<3;slot++)use(e,slot,"node_bio","N_ATTUNE");assertTrue(CampaignPlan.finalReady(s),route);assertTrue(s.supplies.values().stream().anyMatch(n->n<40));for(int slot=0;slot<3;slot++)use(e,slot,"chapter_exit","CH_LEAVE");assertEquals(route,s.endingId);assertTrue(s.campaignComplete);}}
    @Test void enteringANewMapCannotCarryAnOldBlackoutOrInterruptedTask(){var e=chapter(3);e.state.progress.put("blackout:R6",500d);e.state.progress.put("A-17:OBJECT:STAIRS_UP:stairs_up",7d);e.state.progress.put("sync_time_A",2d);CampaignPlan.install(e.state,4);assertFalse(e.state.progress.containsKey("blackout:R6"));assertFalse(e.state.progress.containsKey("A-17:OBJECT:STAIRS_UP:stairs_up"));assertFalse(e.state.progress.containsKey("sync_time_A"));}
    @Test void exhaustedHunterPhysicallyWithdrawsAndRecoversWithoutDying(){var e=chapter(4);var h=e.state.creatures.getFirst();var a=e.state.actor(0);a.roomId=h.roomId;a.x=h.x;a.y=h.y;h.exertion=100;e.advance(.1);assertEquals("RECOVERING",h.state);assertTrue(h.recoveryUntil>e.state.gameTime);double hp=a.hp;var before=h.positionForDefense();e.advance(2);assertEquals(hp,a.hp);assertTrue(before.distance(h.positionForDefense())>0);assertEquals(2,e.state.creatures.size());e.state.gameTime=h.recoveryUntil+.1;h.roomId=a.roomId;h.x=a.x;h.y=a.y;e.advance(.1);assertTrue(a.hp<hp);}
    @Test void finishingTreatmentCannotResurrectAnEcho(){var e=chapter(4);e.state.creatures.clear();var patient=e.state.actor(0);patient.body.get("leftLeg").injury=30;assertTrue(send(e,1,"HEAL",Map.of("recipient",0,"part","leftLeg")).accepted());patient.life="ECHO";patient.hp=0;e.advance(6);assertEquals("ECHO",patient.life);assertEquals(0,patient.hp);}
    private GameEngine chapter(int act){var s=WorldFactory.create("STORY");CampaignPlan.install(s,act);s.phase=Phase.ACTION;for(var a:s.actors){a.connected=true;a.roomId="R0";a.x=150;a.y=360;a.knownRooms.addAll(s.rooms.keySet());}for(String resource:List.of("parts","meds","food","batteries","fuel","filters"))s.supplies.put(resource,40);return new GameEngine(s);}
    private GameEngine.Result send(GameEngine e,int slot,String type,Map<String,?> data){return e.command(slot,new Packet(type,UUID.randomUUID().toString(),data));}
    private void use(GameEngine e,int slot,String id,String action){var f=WorldObjects.get(e.state,id);var a=e.state.actor(slot);a.roomId=f.room();a.x=f.x();a.y=f.y();e.state.creatures.clear();e.state.phase=Phase.ACTION;e.state.remaining=60;var r=send(e,slot,"USE_OBJECT",Map.of("target",id,"action",action));assertTrue(r.accepted(),r.reason());e.advance(CampaignPlan.operation(action).seconds()+.1);assertTrue(a.task.isEmpty(),action);}
    @Test void floorGeometryAndFixturesAreValidAndSeparated(){for(int act=3;act<=6;act++){var e=chapter(act);e.state.doors.values().forEach(d->d.status=DoorStatus.OPEN);for(var f:WorldObjects.all(e.state))assertTrue(e.state.rooms.get(f.room()).contains(f.x(),f.y()),act+"/"+f.id());for(var a:e.state.rooms.values())for(var b:e.state.rooms.values())if(a.floor==b.floor)assertNotNull(Pathfinder.find(e.state,a.id,a.center(),b.id,b.center()));else assertNull(Pathfinder.find(e.state,a.id,a.center(),b.id,b.center()));}}
    @Test void preparationAirlockRequiresPhysicalDeployment(){var e=chapter(4);assertEquals(DoorStatus.SEALED,e.state.doors.get("G3").status);assertFalse(send(e,0,"USE_DOOR",Map.of("target","G3","action","OPEN")).accepted());use(e,0,"camp_gate","CH_DEPLOY");assertTrue(e.state.doors.get("G0").passable());assertTrue(e.state.doors.get("G3").passable());}
    @Test void floorViewCannotTeleportBodyButStairsAreTimed(){var e=chapter(3);assertFalse(send(e,0,"MOVE",Map.of("x",1200,"y",160,"mode","RUN")).accepted());var a=e.state.actor(0);var f=WorldObjects.get(e.state,"stairs_up");a.roomId=f.room();a.x=f.x();a.y=f.y();e.state.creatures.clear();assertTrue(send(e,0,"USE_OBJECT",Map.of("target",f.id(),"action","STAIRS_UP")).accepted());e.advance(7);assertEquals("R1",a.roomId);e.advance(1.1);assertEquals("R5",a.roomId);assertEquals(1,CampaignPlan.floor(e.state,a.roomId));}
    @Test void interruptedStairsDoNotMoveTheBody(){var e=chapter(4);var a=e.state.actor(0);var f=WorldObjects.get(e.state,"stairs_up");a.roomId=f.room();a.x=f.x();a.y=f.y();send(e,0,"USE_OBJECT",Map.of("target",f.id(),"action","STAIRS_UP"));send(e,0,"STOP",Map.of());e.advance(10);assertEquals("R1",a.roomId);}
    @Test void valvesExpireAndPumpNeedsBoth(){var e=chapter(3);var f=WorldObjects.get(e.state,"hydro_pump");assertFalse(WorldObjects.offer(e.state,e.state.actor(0),f,"H_PUMP").enabled());use(e,0,"valve_a","H_VALVE_A");use(e,1,"valve_b","H_VALVE_B");e.state.gameTime+=91;assertFalse(WorldObjects.offer(e.state,e.state.actor(0),f,"H_PUMP").enabled());use(e,0,"valve_a","H_VALVE_A");use(e,1,"valve_b","H_VALVE_B");use(e,0,"hydro_pump","H_PUMP");assertTrue(e.state.flags.contains("hydro_pump"));double flood=e.state.progress.get("hydro_flood");CampaignDirector.update(e,10);assertTrue(e.state.progress.get("hydro_flood")<flood);}
    @Test void floodActuallyRisesAndDamagesLowerFloorOnly(){var e=chapter(3);e.state.actor(1).roomId="R6";e.state.progress.put("hydro_flood",85d);CampaignDirector.update(e,10);assertTrue(e.state.actor(0).hp<100);assertEquals(100,e.state.actor(1).hp);assertTrue(e.state.progress.get("hydro_flood")>85);}
    @Test void chapterExitRequiresOperationsAndPolicy(){var e=chapter(3);assertFalse(CampaignPlan.exitReason(e.state).isEmpty());e.state.flags.addAll(List.of("hydro_pump","ecology_proven","eco_archive"));assertFalse(CampaignPlan.exitReason(e.state).isEmpty());e.state.flags.add("hydro_policy");assertEquals("",CampaignPlan.exitReason(e.state));}
    @Test void personalPermissionCannotAuthorizeAnotherActor(){var e=chapter(4);send(e,0,"PERSONAL_CONSENT",Map.of("procedure","MEMORY","consent",true,"slot",1));assertTrue(e.state.actor(0).permissions.contains("MEMORY"));assertFalse(e.state.actor(1).permissions.contains("MEMORY"));e.state.flags.add("eden_access");assertFalse(WorldObjects.offer(e.state,e.state.actor(1),WorldObjects.get(e.state,"personal_0"),"E_KEY_0").enabled());}
    @Test void refusalGivesLimitedKeyAndPreservesNormalRoutes(){var e=chapter(4);e.state.flags.add("eden_access");use(e,0,"personal_0","E_DECLINE_0");send(e,0,"PERSONAL_CONSENT",Map.of("procedure","MEMORY","consent",true));assertFalse(WorldObjects.offer(e.state,e.state.actor(0),WorldObjects.get(e.state,"personal_0"),"E_KEY_0").enabled());assertEquals(1,CampaignPlan.keys(e.state));assertEquals("",CampaignPlan.routeReason(e.state,"exodus"));assertFalse(CampaignPlan.routeReason(e.state,"awakening").isEmpty());}
    @Test void dormantProxyDoesNotWakeOrAlterMemory(){var e=chapter(4);e.state.flags.add("eden_access");assertFalse(WorldObjects.offer(e.state,e.state.actor(0),WorldObjects.get(e.state,"dormant_archive"),"E_PROXY").enabled());var sleeper=e.state.actor(2);sleeper.life="DORMANT";use(e,0,"dormant_archive","E_PROXY");assertEquals("DORMANT",sleeper.life);assertTrue(sleeper.privateEvidence.isEmpty());assertTrue(e.state.flags.contains("proxy_2"));assertEquals(1,CampaignPlan.keys(e.state));}
    @Test void echoCanRefuseMemoryThroughItsOwnTerminal(){var e=chapter(4);e.state.flags.add("eden_access");e.state.actor(1).life="ECHO";e.state.creatures.clear();assertTrue(send(e,1,"ECHO_INTERFACE",Map.of("action","E_DECLINE_1")).accepted());e.advance(6.1);assertTrue(e.state.flags.contains("declined_1"));assertEquals("ECHO",e.state.actor(1).life);assertFalse(send(e,1,"ECHO_INTERFACE",Map.of("action","E_KEY_0")).accepted());}
    @Test void hunterTransfersOnlyAfterReachingStairsAndWaiting(){var e=chapter(4);e.state.flags.add("eden_access");var h=e.state.creatures.getFirst();var stair=WorldObjects.get(e.state,"stairs_up");h.roomId="R1";h.x=stair.x();h.y=stair.y();for(var a:e.state.actors)a.roomId="R6";CampaignDirector.update(e,.1);assertEquals("R1",h.roomId);e.state.gameTime+=17;CampaignDirector.update(e,.1);assertEquals("R1",h.roomId);e.state.gameTime+=2;CampaignDirector.update(e,.1);assertEquals("R5",h.roomId);assertEquals(2,e.state.creatures.size());}
    @Test void clinicDeadlineFreezesWithTheWorldAndLossIsPermanent(){var e=chapter(5);e.state.phase=Phase.VOTING;e.state.voteRemaining=30;double time=e.state.gameTime;e.advance(20);assertEquals(time,e.state.gameTime);e.state.gameTime=e.state.progress.get("clinic_deadline")+1;CampaignDirector.update(e,.1);assertTrue(e.state.flags.contains("clinic_lost"));assertFalse(WorldObjects.offer(e.state,e.state.actor(0),WorldObjects.get(e.state,"clinic"),"C_CLINIC").enabled());}
    @Test void cacheCostsAndReceiptsCannotDuplicateResources(){var e=chapter(3);var f=WorldObjects.get(e.state,"chapter_cache");var a=e.state.actor(0);a.roomId=f.room();a.x=f.x();a.y=f.y();e.state.creatures.clear();int n=e.state.supplies.get("parts");var p=new Packet("USE_OBJECT","one-cache",Map.of("target",f.id(),"action","CH_CACHE"));assertTrue(e.command(0,p).accepted());e.advance(11);assertTrue(e.command(0,p).accepted());e.advance(11);assertEquals(n+8,e.state.supplies.get("parts"));assertFalse(send(e,0,"USE_OBJECT",Map.of("target",f.id(),"action","CH_CACHE")).accepted());}
    @Test void twoDifferentOwnersMustSynchronizeWithinWindow(){var e=chapter(6);e.state.finalRoute="bastion";e.state.flags.add("vent_ready");use(e,0,"node_a","N_SYNC_A");use(e,0,"node_b","N_SYNC_B");assertFalse(e.state.flags.contains("node_synced"));e.state.gameTime+=61;use(e,1,"node_a","N_SYNC_A");assertFalse(e.state.flags.contains("node_synced"));use(e,0,"node_b","N_SYNC_B");assertTrue(e.state.flags.contains("node_synced"));}
    @Test void echoNeedsPhysicalAnchorAndPermissionForIntegration(){var e=chapter(6);e.state.actor(1).life="ECHO";assertFalse(send(e,1,"ECHO_INTERFACE",Map.of("action","N_ATTUNE")).accepted());e.state.flags.addAll(List.of("echo_anchor","blood_ready"));assertFalse(send(e,1,"ECHO_INTERFACE",Map.of("action","N_ATTUNE")).accepted());for(var a:e.state.actors)a.permissions.add("INTEGRATION");assertTrue(send(e,1,"ECHO_INTERFACE",Map.of("action","N_ATTUNE")).accepted());e.state.creatures.clear();e.advance(11);assertTrue(e.state.flags.contains("attuned_1"));}
    @Test void revokedPermissionBlocksIrreversibleCommit(){var e=chapter(6);e.state.flags.addAll(List.of("route_awakening","keys_verified","echo_anchor","node_synced"));for(var a:e.state.actors)a.permissions.add("STOP_CYCLES");var f=WorldObjects.get(e.state,"node_final");var a=e.state.actor(0);a.roomId=f.room();a.x=f.x();a.y=f.y();e.state.creatures.clear();assertTrue(send(e,0,"USE_OBJECT",Map.of("target",f.id(),"action","N_STOP")).accepted());send(e,1,"PERSONAL_CONSENT",Map.of("procedure","STOP_CYCLES","consent",false));e.advance(16);assertFalse(e.state.flags.contains("cycles_stopped"));}
    @Test void allSixRoutesRequireDifferentPhysicalWork(){var required=Map.of("exodus","convoy_ready","bastion","vent_ready,node_synced","cleansing","thermal_ready","symbiosis","blood_ready","protocol","protocol_signed","awakening","cycles_stopped");for(String route:CampaignPlan.ROUTES){var e=chapter(6);e.state.finalRoute=route;assertFalse(CampaignPlan.finalReady(e.state),route);e.state.flags.addAll(Arrays.asList(required.get(route).split(",")));if(route.equals("symbiosis"))for(var a:e.state.actors){a.permissions.add("INTEGRATION");e.state.flags.add("attuned_"+a.slot);}assertTrue(CampaignPlan.finalReady(e.state),route);for(var a:e.state.actors)a.life="EVACUATED";CampaignDirector.finishStage(e);assertTrue(e.state.campaignComplete);assertEquals(route,e.state.endingId);assertTrue(e.state.epilogue.size()>=8);assertFalse(send(e,0,"CONTINUE_CHAPTER",Map.of()).accepted());}}
    @Test void cleansingDelaysButNeverRemovesCreatures(){var e=chapter(6);e.state.flags.add("runoff_cut");var f=WorldObjects.get(e.state,"node_control");CampaignDirector.complete(e,e.state.actor(0),f,"N_HEAT");assertEquals(2,e.state.creatures.size());assertTrue(e.state.creatures.stream().allMatch(c->c.suppressedUntil>e.state.gameTime));}
    @Test void nodeDeadlineProducesRealFall(){var e=chapter(6);e.state.gameTime=e.state.progress.get("node_deadline")+1;CampaignDirector.update(e,.1);assertTrue(e.state.campaignComplete);assertEquals("fall",e.state.endingId);assertTrue(e.state.actors.stream().allMatch(a->a.life.equals("ECHO")));assertEquals(2,e.state.creatures.size());}
    @Test void saveRetainsFloorsPermissionTimersAndFinalRoute(@TempDir Path dir)throws Exception{var e=chapter(6);e.state.finalRoute="protocol";e.state.actor(1).permissions.add("MEMORY");var file=dir.resolve("node.json");SaveStore.save(file,e.state);var s=SaveStore.load(file);assertEquals(1,s.rooms.get("R6").floor);assertTrue(s.actor(1).permissions.contains("MEMORY"));assertEquals("protocol",s.finalRoute);assertEquals(e.state.progress,s.progress);}
    @Test void continuingPreservesDamageInventoryAndArchivedThreats(){var e=chapter(3);e.state.phase=Phase.GAME_OVER;e.state.actor(0).hp=61;for(var a:e.state.actors)a.life="EVACUATED";int kits=e.state.actor(0).inventory.get("medkit").count;for(int i=0;i<2;i++)assertTrue(send(e,i,"CONTINUE_CHAPTER",Map.of()).accepted());assertEquals(3,e.state.currentAct);send(e,2,"CONTINUE_CHAPTER",Map.of());assertEquals(4,e.state.currentAct);assertEquals(61,e.state.actor(0).hp);assertEquals(kits,e.state.actor(0).inventory.get("medkit").count);assertEquals(2,e.state.visitedLocations.get("chapter_3").creatures.size());assertTrue(e.view(0).visitedLocations.isEmpty());}
}
